INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "蓝玉", "aliases": ["藍玉"], "era": "明", "birth_year": null, "death_year": null, "description": "明初将领。本纪载其以都督身份随西平侯沐英征讨西番。", "biography": null, "status": "draft", "id": "b9acd0d9-69b0-5100-b509-064627c8b88a"}, {"name": "沐英", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "定远人，父母亡，朱元璋收养、赐朱姓。", "biography": null, "status": "draft", "id": "c9e9d78a-2557-5892-876e-b1e99dd22bed"}, {"name": "傅友德", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "原陈友谅小孤山守将，1361年降吴。", "biography": null, "status": "draft", "id": "052c6ab9-234a-5d89-9bad-ec31f6774b50"}, {"status": "draft", "name": "马氏（郭子兴养女）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "宿州马公最小的女儿，父死后为郭子兴养女，1352年嫁朱元璋；原称季女，不补年龄或俗传名字。", "biography": null, "id": "4b0e7356-b115-5755-bcaf-fc1dd998b656"}, {"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷在谨身殿赐宴首次使用九奏乐", "description": "朱元璋在谨身殿宴请群臣，首次使用九奏乐。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年正月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "90afdd87-555b-5363-b295-74493191089b"}, {"title": "曹震和王弼攻下威楚路", "description": "景川侯曹震和定远侯王弼攻下威楚路。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "862f36ce-1a44-5a77-95a2-6688ea4f01d8"}, {"title": "曲靖宣慰司和云南多路向明军归降", "description": "原属元军的曲靖宣慰司和中庆、澂江、武定各路向明军归降，本纪至此记“云南平”。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年正月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1bfaa41e-1fda-58b2-abab-9239ccd7c2f9"}, {"title": "明廷为死刑囚犯减刑", "description": "朝廷对原判死刑的囚犯减刑。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年正月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5e90f952-a196-54b7-a619-37cd69bdf9db"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年正月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4f25b428-2041-5c49-bb6e-7db0b6b04b25"}, {"title": "明廷命朝觐官员各荐一人", "description": "明廷命各地入朝觐见的官员各荐举一名自己了解的人。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年正月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d45ccb31-6e48-5ae4-9bf9-dbf89460cdc8"}, {"title": "黄河在河南决口，明廷派李祺赈济", "description": "黄河在河南决口，明廷命驸马都尉李祺前往救济。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年二月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "07ebc399-77a2-5508-83a7-206ec347b190"}, {"title": "明廷诏告云南平定", "description": "朝廷因云南平定而向天下发布诏告。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年二月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "85da62e0-caa0-5d52-b6a7-d48bc029a1b6"}, {"title": "蓝玉和沐英攻占大理等地", "description": "蓝玉和沐英攻占大理，随后分兵进取鹤庆、丽江和金齿，先后攻下各地。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年闰二月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f339c928-6027-548f-9b1c-dc200cfccfc1"}, {"title": "黄河在朝邑决口", "description": "本纪记载，黄河在朝邑决口。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年三月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f70af0d1-2682-550f-972e-626082391f5a"}, {"title": "明廷迁送元梁王等人的家属到耽罗", "description": "朝廷将原元朝梁王把匝剌瓦儿密、威顺王之子伯伯等人的家属迁往耽罗。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年四月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fef5d293-1d62-5c11-abcf-a97719530fd8"}, {"title": "明廷诏令各地祭祀孔子", "description": "朝廷下诏，各地共同实行祭祀孔子的礼制。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年四月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e070e90f-5a42-58e4-8b66-871b2abf6b98"}, {"title": "明廷免征畿内等地税粮", "description": "朝廷免去畿内、浙江、江西、河南和山东的税粮。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年四月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f10b0304-cd95-532e-b566-321b65daa2d9"}, {"title": "太学落成并举行祭孔礼", "description": "太学落成，明廷举行释奠礼，祭祀孔子。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年五月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b7afa281-61b5-5ee8-8e97-8a8eac054f56"}, {"title": "朱元璋驳回王允道开办磁州铁冶的建议", "description": "广平府吏王允道请求在磁州开办铁冶。朱元璋说，军器已经充足，百姓已有生计，开办铁冶既无益于国，又会扰民。他命人杖责王允道，并将其流放到岭南。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年五月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f6b193f5-27b1-55e9-a2f2-04aadd212153"}, {"title": "明廷派使者访求通经修行的士人", "description": "朝廷派出行人，寻访通晓经书、品行良好的士人。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年五月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ed8051f3-5a73-58da-8d93-e97a8c1b052c"}, {"title": "黄河在荥泽和阳武决口", "description": "本纪记载，黄河在荥泽、阳武决口。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年七月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "82b85fc7-0d42-5401-a4d2-7462b11ee339"}, {"title": "明廷撤销四辅官", "description": "朝廷撤销四辅官。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年七月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8fa242c6-5216-5b89-a095-77fa3534dfd3"}, {"title": "傅友德和沐英在乌撒战事中取胜", "description": "傅友德与沐英率军进攻本纪所称的乌撒蛮，大败对方。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年七月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "15f257ea-1b61-5c71-9122-7914e8275853"}, {"title": "明廷恢复科举并规定三年一试", "description": "朝廷恢复设科取士，并确立每三年举行一次的制度。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年八月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "71245dbd-ab24-5305-a66a-d41e0222329c"}, {"title": "马皇后去世", "description": "本纪记载，皇后在八月丙戌去世。下段称她为孝慈皇后。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年八月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2600f639-35da-549e-aa29-29113f5d4fab"}, {"title": "唐胜宗和耿炳文在陕西屯田", "description": "延安侯唐胜宗、长兴侯耿炳文赴陕西屯田。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年八月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5bddbbb9-dd49-59a2-b0c4-0cdf3c4488a0"}, {"title": "曾泰被擢为户部尚书", "description": "朝廷提拔秀才曾泰担任户部尚书。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年八月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b0e08378-b5e1-57f8-9e4f-5d53fbe7db4d"}, {"title": "明廷命应召秀才分六科试用", "description": "朝廷命已经应征到京的秀才分为六科试用。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年八月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "288772df-be0d-5d61-a012-958b1f723c28"}, {"title": "吏部引见郑韬等三千七百余名士人", "description": "吏部引导郑韬等三千七百多名士人入见。朝廷命他们荐举人才，再派使者征召，赐给这些士人宝钞。随后朝廷分别授予他们布政使、参政等官职。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年九月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4ce63e75-12b6-5782-8a4a-898bce59af4a"}, {"title": "孝慈皇后葬于孝陵", "description": "本纪记载，朝廷将孝慈皇后安葬在孝陵。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年九月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7daf8d7f-ec70-515c-9973-dfe6f6aaf255"}, {"title": "明廷设置都察院", "description": "朝廷设置都察院。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年十月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cee22ae8-f094-50ad-9f9c-28892ff3a1e8"}, {"title": "明廷复查在押囚犯案件", "description": "明廷在这一日复查囚犯案件。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年十月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "67ef4325-57d4-52ef-92cc-eb7c60000138"}, {"title": "徐达在十月返回", "description": "本纪记载，徐达于十月甲辰返回。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年十月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6c125234-5caf-5329-a112-bbf6d72c372f"}, {"title": "广东战事平定后明廷命赵庸班师", "description": "本纪记载，广东战事平定后，朝廷命赵庸返回。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "50b5ab33-3cf2-5210-a867-30fb55b5785f"}, {"title": "明廷设置殿阁大学士", "description": "朝廷设置殿阁大学士，由邵质、吴伯宗、宋讷和吴沉担任。", "start_year": 1382, "end_year": 1382, "time_original": "洪武十五年十一月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "19fcd2cb-2684-5161-bac9-7e07b1df4297"}, {"title": "明廷赈济北平受灾屯田士卒", "description": "朝廷下令救济北平受灾的屯田士卒。", "start_year": 1383, "end_year": 1383, "time_original": "洪武十五年十二月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "99237906-fc85-5e22-9fc7-70ff8b5f334b"}, {"title": "薛显处理山西军务", "description": "朝廷命永城侯薛显处理山西军务。", "start_year": 1383, "end_year": 1383, "time_original": "洪武十五年十二月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "20b404d7-f848-52d9-b353-cc80879bbc89"}, {"title": "爪哇等地向明廷入贡", "description": "本纪记载，这一年爪哇、琉球、乌斯藏和占城向明廷入贡，各批来使的日期未单独列出。 按原历纪年，事情发生在公元1382至1383年之间。", "start_year": null, "end_year": null, "time_original": "洪武十五年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "35731e16-b79c-514f-9689-9b29522a336c"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1383, "end_year": 1383, "time_original": "洪武十六年正月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "45e74b1c-127f-5370-a0b9-d210424057bd"}, {"title": "徐达奉命镇守北平", "description": "本纪记载，徐达于此日镇守北平。", "start_year": 1383, "end_year": 1383, "time_original": "洪武十六年正月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "eb009f74-713b-5d9f-9c46-0b3cd8ef098c"}, {"title": "明廷开始命各地学校每年荐送生员", "description": "朝廷开始要求各地学校每年向京师荐送生员。", "start_year": 1383, "end_year": 1383, "time_original": "洪武十六年二月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1cde830d-33bd-5bdb-89b3-642c7ae6e198"}, {"title": "征南部队奉召返回，沐英留镇云南", "description": "朝廷召回南征部队，沐英继续留守云南。", "start_year": 1383, "end_year": 1383, "time_original": "洪武十六年三月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a370a639-56b2-56a3-9324-96ee7e11ea70"}, {"title": "明廷免除凤阳和临淮百姓的赋役", "description": "朝廷免除凤阳、临淮两县百姓的徭役和赋税，命此后各代沿行。", "start_year": 1383, "end_year": 1383, "time_original": "洪武十六年三月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "07d63d2e-fef5-5c91-a474-9d294876510a"}, {"title": "明廷免征畿内各府田租", "description": "朝廷免去畿内各府的田租。", "start_year": 1383, "end_year": 1383, "time_original": "洪武十六年五月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "496db062-ca91-55ad-a0d8-a4e008137eee"}, {"title": "明廷免去指定州县养马户的田租", "description": "朝廷免除畿内十二州县养马户一年的田租，其中滁州免两年。", "start_year": 1383, "end_year": 1383, "time_original": "洪武十六年六月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4f051691-86e9-55ee-9b84-bba447e8417a"}, {"title": "明廷分派御史复查囚案", "description": "朝廷分派御史到各处复查囚犯案件。", "start_year": 1383, "end_year": 1383, "time_original": "洪武十六年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5bb6e0b4-4cca-5f01-aa01-89953c7878c6"}]'::jsonb)
